fun testByte() {
    println("== ByteArray")
    val a = byteArrayOf(3, 1, 2, 3, 5)
    val b = byteArrayOf(2, 5, 7)
    val e0 = a.copyOfRange(0, 0)
    println(a.sortedBy { it.toString() })
    println(a.sortedByDescending { it.toString() })
    println(a.sortedWith(compareBy<Byte> { it.toString() }))
    println(a.distinctBy { it.toString() })
    println(a.associateByTo(LinkedHashMap<String, String>(), { it.toString() }, { "v" + it }))
    println(a.flatMapIndexedTo(ArrayList<String>()) { i, e -> listOf(i.toString(), e.toString()) })
    println(a.groupByTo(LinkedHashMap<String, MutableList<String>>(), { it.toString() }, { "x" + it }))
    println(a.intersect(b.asIterable()))
    println(a.subtract(b.asIterable()))
    println(a.union(b.asIterable()))
    println(a.maxOfWith(naturalOrder<String>()) { it.toString() })
    println(a.minOfWith(naturalOrder<String>()) { it.toString() })
    println(a.maxOfWithOrNull(naturalOrder<String>()) { it.toString() })
    println(a.minOfWithOrNull(naturalOrder<String>()) { it.toString() })
    println(e0.maxOfWithOrNull(naturalOrder<String>()) { it.toString() })
    println(e0.minOfWithOrNull(naturalOrder<String>()) { it.toString() })
    try { e0.maxOfWith(naturalOrder<String>()) { it.toString() } } catch (e: NoSuchElementException) { println("NSEE") }
    try { e0.minOfWith(naturalOrder<String>()) { it.toString() } } catch (e: NoSuchElementException) { println("NSEE") }
    println(a.reduceIndexedOrNull { i, acc, e -> (acc + e).toByte() })
    println(e0.reduceIndexedOrNull { i, acc, e -> (acc + e).toByte() })
    println(a.reduceRightIndexed { i, e, acc -> (acc + e).toByte() })
    println(a.reduceRightIndexedOrNull { i, e, acc -> (acc + e).toByte() })
    println(e0.reduceRightIndexedOrNull { i, e, acc -> (acc + e).toByte() })
    println(a.reduceRightOrNull { e, acc -> (acc + e).toByte() })
    println(e0.reduceRightOrNull { e, acc -> (acc + e).toByte() })
    println(a.runningReduceIndexed { i, acc, e -> (acc + e).toByte() })
}

