fun testGeneric() {
    println("== Array<T>")
    val a = arrayOf("c", "a", "b", "c", "e")
    println(a.plusElement("z").toList())
    val n: Array<String?> = arrayOf("x", "y")
    println(n.requireNoNulls().toList())
    try { arrayOf<String?>("x", null).requireNoNulls() } catch (e: IllegalArgumentException) { println("IAE") }
    val nn: Array<String?> = arrayOf("x", null, "y")
    println(nn.filterNotNullTo(ArrayList<String>()))
    println(a.associateByTo(LinkedHashMap<String, String>(), { it }, { "v" + it }))
    println(a.flatMapIndexedTo(ArrayList<String>()) { i, e -> listOf(i.toString(), e) })
    println(a.groupByTo(LinkedHashMap<String, MutableList<String>>(), { it }, { "x" + it }))
    println(a.mapIndexedNotNullTo(ArrayList<String>()) { i, e -> if (i % 2 == 0) e else null })
    println(a.intersect(listOf("a", "e", "q")))
    println(a.subtract(listOf("a", "e", "q")))
    println(a.union(listOf("a", "e", "q")))
    println(a.maxOfWith(naturalOrder<String>()) { it + "!" })
    println(a.minOfWith(naturalOrder<String>()) { it + "!" })
    println(a.maxOfWithOrNull(naturalOrder<String>()) { it + "!" })
    println(a.minOfWithOrNull(naturalOrder<String>()) { it + "!" })
    println(a.reduceIndexedOrNull { i, acc, e -> acc + e + i })
    println(a.reduceRightIndexed { i, e, acc -> acc + e + i })
    println(a.reduceRightIndexedOrNull { i, e, acc -> acc + e + i })
    println(a.reduceRightOrNull { e, acc -> acc + e })
    println(a.runningReduceIndexed { i, acc, e -> acc + e + i })
    println(emptyArray<String>().reduceRightOrNull { e, acc -> acc + e })
    println(emptyArray<String>().reduceRightIndexedOrNull { i, e, acc -> acc + e })
    println(emptyArray<String>().reduceIndexedOrNull { i, acc, e -> acc + e })
    println(emptyArray<String>().runningReduceIndexed { i, acc, e -> acc + e })
    println(emptyArray<String>().maxOfWithOrNull(naturalOrder<String>()) { it })
    println(mapOf(1 to "a", 2 to "b").maxOfWithOrNull(naturalOrder<String>()) { it.value })
    println(mapOf(1 to "a", 2 to "b").minOfWithOrNull(naturalOrder<String>()) { it.value })
}

fun main() {
    testByte()
    testShort()
    testInt()
    testLong()
    testFloat()
    testDouble()
    testChar()
    testBoolean()
    testGeneric()
}
